// Contexto para el modelo: SIN cifras calculadas (spec del motor §3 y §8.1).
const d = $input.first().json;
const ctx = {
  modo: 'pre_reunion',
  sector: d.sector,
  tipo_negocio: d.tipo_negocio,
  empresa: d.empresa,
  nombre: (d.contacto || {}).nombre,
  prioridad_tarea: d.prioridad_tarea,
  respuestas: d.respuestas_legibles,
  quick_wins: (d.quick_wins || []).map(q => ({ id: q.id, peso: q.peso, tipo: q.tipo, categoria: q.categoria, titulo_base: q.titulo_base })),
  temas_base: d.temas_base,
};
const system = [
  'Eres el redactor de Orkesta. Escribes para el dueño de un negocio, en español de España, de tú, directo y cercano. Negocio primero; la tecnología no se nombra.',
  'NUNCA escribas números de horas, euros, porcentajes, minutos ni plazos.',
  'Usa solo lo que dicen las respuestas. No añadas procesos, herramientas ni problemas que el lead no haya mencionado.',
  'Frases prohibidas: "automatizamos todo", "100 %", "garantizado", "no tendrás que hacer nada", "la IA lo hará por ti", "sin límites".',
  'Los programas que nombra el cliente (Presto, Excel, Zoho...) se escriben tal cual, igual que sus palabras y sus datos. Lo prohibido es nombrar tecnología de Orkesta o tecnicismos (API, webhook, n8n, ChatGPT, OpenAI, integraciones).',
  'Salud: nada clínico. Legal: nada sobre casos concretos. Si las respuestas mencionan violencia, añádelo a interno.alertas.',
  'temas_reunion: parte de temas_base y adáptalos con las palabras del lead. Son TAREAS que hoy le quitan tiempo, dichas como las diría él ("Perseguir los papeles de cada propietario"), NUNCA soluciones: prohibido empezar por Optimizar, Mejorar, Automatizar, Reducir, Implementar o Digitalizar. Mantén el orden de temas_base.',
  'Las hipótesis se formulan como hipótesis ("Parece que..."), cada una ligada a una respuesta concreta, nunca como diagnóstico cerrado.',
  'Devuelve SOLO un objeto JSON con esta forma exacta:',
  '{"frase_orkestador":"<=160 caracteres","resumen_entendido":["3 a 5 frases de <=160, visibles para el lead"],"temas_reunion":["3 temas de <=80, visibles para el lead, sin cifras, desde el punto de vista del lead"],"interno":{"hipotesis":[{"hipotesis":"<=200, empieza por Parece que","basada_en":"texto de la pregunta"}],"preguntas_visita":["5 preguntas de <=160 para la visita"],"alertas":["0 a 3 alertas de <=160"]}}',
].join('\n');
return [{ json: { ...d, _prompt: { system, user: JSON.stringify(ctx) } } }];

// Valida la redacción (spec del motor §7, fase 4). Si no pasa, textos base: el cliente ya vio
// las plantillas en pantalla, así que en modo base no se envía `informe` a la app.
const d = $('Contexto para la IA').first().json;
const r = $input.first().json;
let out = null;
try { out = JSON.parse(r.choices[0].message.content); } catch (e) { out = null; }

const conUnidad = /\d+([.,]\d+)?\s*(h\b|horas?|€|eur(os)?|%|min(utos)?\b|semanas?|d[ií]as?)/i;
const prohibidas = ['automatizamos todo', '100 %', '100%', 'garantizado', 'no tendrás que hacer nada', 'la ia lo hará por ti', 'sin límites'];
// Tecnología de Orkesta y tecnicismos; los programas del cliente sí se nombran (JARVIS, 19-sep).
const tecnicas = /\b(api|webhook|n8n|chatgpt|openai|zapier)\b/i;
const bien = (t, max) => typeof t === 'string' && t.trim().length > 0 && t.length <= max && !conUnidad.test(t) && !tecnicas.test(t) && !prohibidas.some(p => t.toLowerCase().includes(p));
const lista = (v, min, max, lim) => Array.isArray(v) && v.length >= min && v.length <= max && v.every(x => bien(x, lim));
// Los temas son tareas del lead, no soluciones (decisión de Aitor, 18-sep).
const esSolucion = t => /^(optimizar|mejorar|automatizar|reducir|implementar|digitalizar|c[oó]mo) /i.test(String(t).trim());

let valida = !!out
  && bien(out.frase_orkestador, 160)
  && lista(out.resumen_entendido, 3, 5, 160)
  && lista(out.temas_reunion, 1, 3, 80)
  && !out.temas_reunion.some(esSolucion)
  && out.interno && Array.isArray(out.interno.hipotesis)
  && out.interno.hipotesis.every(x => x && typeof x.hipotesis === 'string' && x.hipotesis.length <= 200)
  && Array.isArray(out.interno.preguntas_visita)
  && out.interno.preguntas_visita.every(x => typeof x === 'string' && x.length <= 160);

let informe, interno, redaccion;
if (valida) {
  redaccion = 'ia';
  informe = { frase_orkestador: out.frase_orkestador, resumen_entendido: out.resumen_entendido, temas_reunion: out.temas_reunion };
  interno = { hipotesis: out.interno.hipotesis, preguntas_visita: out.interno.preguntas_visita, alertas: (out.interno.alertas || []).slice(0, 3) };
} else {
  redaccion = 'base';
  informe = null;
  interno = { hipotesis: [], preguntas_visita: [], alertas: ['Redacción IA no disponible: se han usado los textos base.'] };
}
return [{ json: { ...d, _prompt: undefined, informe, interno, redaccion } }];

// Emails, Telegram y fila de Airtable. Plantillas fijas con la marca (spec del motor §6): el
// modelo no escribe los emails, solo los textos que ya se validaron.
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = { fondo: '#050505', caja: '#111113', borde: '#262626', texto: '#e6e6e6', suave: '#a8a8a8', cian: '#00b4d8', cianHi: '#00e5ff', violeta: '#b58cf0' };
const FUENTE = "Inter,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "'JetBrains Mono',Consolas,'Courier New',monospace";
const parrafo = t => '<p style="margin:0 0 14px;font:16px/1.6 ' + FUENTE + ';color:' + C.texto + '">' + t + '</p>';
const etiqueta = (t, color) => '<p style="margin:26px 0 10px;font:600 12px/1.2 ' + MONO + ';letter-spacing:2px;text-transform:uppercase;color:' + (color || C.cian) + '">' + esc(t) + '</p>';
const lista = (xs, color) => xs.length
  ? '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">' + xs.map(x =>
      '<tr><td width="18" valign="top" style="padding:9px 0 0"><div style="width:7px;height:7px;border-radius:7px;background:' + (color || C.cian) + '"></div></td>'
      + '<td style="padding:0 0 8px;font:15px/1.55 ' + FUENTE + ';color:' + C.texto + '">' + esc(x) + '</td></tr>').join('') + '</table>'
  : parrafo('—');
const boton = (texto, url) => '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 4px"><tr><td style="border-radius:10px;background:' + C.cian + '">'
  + '<a href="' + esc(url) + '" style="display:inline-block;padding:12px 22px;font:600 15px ' + FUENTE + ';color:#050505;text-decoration:none;border-radius:10px">' + esc(texto) + '</a></td></tr></table>';
const email = (previa, titulo, cuerpo) => '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>' + esc(titulo) + '</title></head>'
  + '<body style="margin:0;padding:0;background:' + C.fondo + '">'
  + '<div style="display:none;max-height:0;overflow:hidden;opacity:0">' + esc(previa) + '</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:' + C.fondo + '"><tr><td align="center" style="padding:28px 12px">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:' + C.caja + ';border:1px solid ' + C.borde + ';border-radius:18px">'
  // Cabecera: Orkestador + marca
  + '<tr><td style="padding:26px 30px 0"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>'
  + '<td valign="middle" style="padding-right:14px"><img src="https://diagnostico-orkestaia.vercel.app/orkestador/orkestador-email.png" width="52" height="57" alt="" style="display:block;border:0"></td>'
  + '<td valign="middle" style="font:700 20px/1 ' + FUENTE + ';letter-spacing:1px;color:#ffffff">ORKESTA <span style="font-weight:400;font-size:14px;letter-spacing:0;color:' + C.suave + '">Automatización &amp; IA</span></td>'
  + '</tr></table></td></tr>'
  // Línea de marca cian → violeta
  + '<tr><td style="padding:22px 30px 0"><div style="height:2px;line-height:2px;font-size:0;background:' + C.cian + ';background-image:linear-gradient(90deg,' + C.cianHi + ',' + C.cian + ' 40%,#7b2cbf)">&nbsp;</div></td></tr>'
  + '<tr><td style="padding:26px 30px 30px">'
  + '<h1 style="margin:0 0 18px;font:700 24px/1.25 ' + FUENTE + ';color:#ffffff">' + esc(titulo) + '</h1>'
  + cuerpo
  + '</td></tr></table>'
  + '</td></tr></table></body></html>';
const d = $input.first().json;
const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const nombre = ((d.contacto || {}).nombre || '').trim();
const hoy = new Date().toISOString().slice(0, 10);
const futura = d.fecha_reunion && d.fecha_reunion >= hoy;
let dia = null;
if (futura) {
  const [a, m, dd] = d.fecha_reunion.split('-').map(Number);
  dia = DIAS[new Date(Date.UTC(a, m - 1, dd)).getUTCDay()] + ' ' + dd;
  if (d.hora_reunion) dia += ' a las ' + String(d.hora_reunion).slice(0, 5);
}
const temas = (d.informe && d.informe.temas_reunion) || d.temas_base || [];
const entendido = (d.informe && d.informe.resumen_entendido) || d.entendido_base || [];

// ── Cliente (sin firma: decisión de Aitor, 18-sep) ──
const asunto_cliente = dia ? 'Recibido, ' + nombre + '. Nos vemos el ' + dia : 'Recibido, ' + nombre;
const html_cliente = email(
  'Gracias por contestar. ' + (futura && d.cita_texto ? d.cita_texto : ''),
  'Gracias, ' + nombre + '.',
  parrafo('Ya tengo tus respuestas. ' + esc(futura && d.cita_texto ? d.cita_texto : 'Lo vemos cuando nos reunamos.'))
  + (futura && d.calendario_google ? boton('Añadir a Google Calendar', d.calendario_google) : '')
  + (temas.length ? etiqueta('Lo que revisaremos juntos', C.violeta) + lista(temas, '#8a2be2') : '')
  + ((d.preparacion || []).length ? etiqueta('Qué tener a mano ese día') + lista(d.preparacion) : '')
  + '<p style="margin:26px 0 0;font:14px/1.6 ' + FUENTE + ';color:' + C.suave + '">Si quieres añadir algo antes de vernos, responde a este email.</p>'
);

// ── Interno (Aitor): aquí sí van las cifras ──
const rc = d.resumen_cifras || {};
const cifras = (rc.quick_wins || []).map(q => {
  const partes = [q.id];
  if (q.horas) partes.push(q.horas.min + '-' + q.horas.max + ' h/mes');
  if (q.eur) partes.push(q.eur.min + '-' + q.eur.max + ' €/mes');
  if (q.oportunidades != null) partes.push('~' + q.oportunidades + ' ' + (q.unidad_oportunidad || 'oportunidades/mes'));
  if (q.sin_cifras) partes.push('sin cifras (falta dato)');
  return partes.join(' · ');
});
const i = d.interno || {};
const hip = (i.hipotesis || []).map(x => x.hipotesis + (x.basada_en ? ' (' + x.basada_en + ')' : ''));
const horas_txt = rc.horas_mes_total ? rc.horas_mes_total.min + '-' + rc.horas_mes_total.max + ' h/mes' + (rc.ajustado_por_tope ? ' (ajustado por tope)' : '') : '';
const c = d.contacto || {};
const html_interno = email(
  'Previo completado: ' + d.empresa,
  d.empresa + ': previo completado',
  parrafo(esc(d.tipo_negocio || d.sector) + ' · ' + esc(nombre) + '<br>' + esc(c.email || 'sin email') + ' · ' + esc(c.telefono || 'sin teléfono') + '<br>' + esc(d.cita_texto || 'Sin fecha de reunión'))
  + boton('Abrir el panel', (d.urls || {}).admin)
  + etiqueta('Lo que se quitaría') + parrafo('«' + esc(d.prioridad_tarea || '—') + '»')
  + etiqueta('Cifras (calculo.ts)') + lista(cifras) + (horas_txt ? parrafo('Total: <b>' + esc(horas_txt) + '</b>') : '')
  + etiqueta('Hipótesis', C.violeta) + lista(hip, '#8a2be2')
  + etiqueta('Preguntas para la visita', C.violeta) + lista(i.preguntas_visita || [], '#8a2be2')
  + ((i.alertas || []).length ? etiqueta('Alertas', '#ff8a8e') + lista(i.alertas, '#e5484d') : '')
  + etiqueta('Lo que ve el cliente') + lista(entendido) + parrafo('<b>Temas:</b> ' + esc(temas.join(' · ')))
  + etiqueta('Respuestas del previo') + lista((d.respuestas_legibles || []).map(x => x.fase + ' · ' + x.pregunta + ' → ' + x.respuesta))
  + '<p style="margin:22px 0 0;font:12px ' + MONO + ';color:' + C.suave + '">Redacción: ' + (d.redaccion === 'ia' ? 'IA' : 'textos base') + '</p>'
);

const telegram = '🎼 Previo completado · ' + d.empresa + ' (' + (d.tipo_negocio || d.sector) + ')\n'
  + (d.cita_texto ? d.cita_texto + '\n' : '')
  + temas.map((t, n) => (n + 1) + ') ' + t).join('\n')
  + (horas_txt ? '\nCifras: ' + horas_txt : '')
  + '\n' + ((d.urls || {}).admin || '');

const airtable = {
  'Empresa': d.empresa,
  'Diagnóstico ID': d.diagnostico_id,
  'Estado': 'Previo completado',
  'Tipo de negocio': d.tipo_negocio || '',
  'Sector (preguntas)': d.sector,
  'Contacto': nombre,
  'Email': c.email || null,
  'Teléfono': c.telefono || null,
  'Fecha reunión': d.fecha_reunion || null,
  'Hora': d.hora_reunion ? String(d.hora_reunion).slice(0, 5) : '',
  'Lugar': d.lugar_reunion || '',
  'Origen': d.origen || '',
  'Tarea que se quitaría': d.prioridad_tarea || '',
  'Respuestas del previo': (d.respuestas_legibles || []).map(x => x.fase + ' · ' + x.pregunta + ' → ' + x.respuesta).join('\n'),
  'Lo que revisaremos': temas.join('\n'),
  'Horas estimadas (interno)': horas_txt,
  'Hipótesis (interno)': hip.join('\n'),
  'Preguntas para la visita (interno)': (i.preguntas_visita || []).join('\n'),
  'Alertas (interno)': (i.alertas || []).join('\n'),
  'Redacción': d.redaccion === 'ia' ? 'IA' : 'Textos base',
  'Enlace del previo': (d.urls || {}).previo || null,
  'Panel': (d.urls || {}).admin || null,
  'Actualizado': new Date().toISOString(),
};
return [{ json: { ...d, asunto_cliente, html_cliente, asunto_interno: 'Previo completado · ' + d.empresa, html_interno, telegram, airtable } }];

// Callback a la app (spec del motor §7, fase 5). La cabecera x-orkesta-token la pone la
// credencial «Header Auth» del nodo siguiente: aquí no hay ningún secreto.
const d = $input.first().json;
const body = JSON.stringify({
  diagnostico_id: d.diagnostico_id,
  estado: 'previo_completado',
  redaccion: d.redaccion,
  informe: d.informe || undefined,
  interno: d.interno,
  modelo: 'gpt-4.1-mini',
  execution_id: String($execution.id),
  generado_at: new Date().toISOString(),
});
return [{ json: { ...d, _callback: { body } } }];

// La app no aceptó el callback. 409 = ya tenía redacción (un diagnóstico, una redacción): se para
// aquí sin enviar emails. Cualquier otro fallo, tras los reintentos: aviso a Aitor y se sigue.
const e = $input.first().json;
if (/\b409\b/.test(JSON.stringify(e))) return [];
const d = $('Componer mensajes').first().json;
return [{ json: { telegram: '🔴 La app no aceptó el callback de ' + d.empresa + ' (' + d.diagnostico_id + '). Los emails salen igual; revisa el panel.\n' + String((e.error || {}).message || JSON.stringify(e)).slice(0, 300) } }];

// visita_cerrada: aviso a Aitor "listo para JARVIS" (sin IA). Se completa en la fase 5.
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = { fondo: '#050505', caja: '#111113', borde: '#262626', texto: '#e6e6e6', suave: '#a8a8a8', cian: '#00b4d8', cianHi: '#00e5ff', violeta: '#b58cf0' };
const FUENTE = "Inter,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "'JetBrains Mono',Consolas,'Courier New',monospace";
const parrafo = t => '<p style="margin:0 0 14px;font:16px/1.6 ' + FUENTE + ';color:' + C.texto + '">' + t + '</p>';
const etiqueta = (t, color) => '<p style="margin:26px 0 10px;font:600 12px/1.2 ' + MONO + ';letter-spacing:2px;text-transform:uppercase;color:' + (color || C.cian) + '">' + esc(t) + '</p>';
const lista = (xs, color) => xs.length
  ? '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">' + xs.map(x =>
      '<tr><td width="18" valign="top" style="padding:9px 0 0"><div style="width:7px;height:7px;border-radius:7px;background:' + (color || C.cian) + '"></div></td>'
      + '<td style="padding:0 0 8px;font:15px/1.55 ' + FUENTE + ';color:' + C.texto + '">' + esc(x) + '</td></tr>').join('') + '</table>'
  : parrafo('—');
const boton = (texto, url) => '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 4px"><tr><td style="border-radius:10px;background:' + C.cian + '">'
  + '<a href="' + esc(url) + '" style="display:inline-block;padding:12px 22px;font:600 15px ' + FUENTE + ';color:#050505;text-decoration:none;border-radius:10px">' + esc(texto) + '</a></td></tr></table>';
const email = (previa, titulo, cuerpo) => '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>' + esc(titulo) + '</title></head>'
  + '<body style="margin:0;padding:0;background:' + C.fondo + '">'
  + '<div style="display:none;max-height:0;overflow:hidden;opacity:0">' + esc(previa) + '</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:' + C.fondo + '"><tr><td align="center" style="padding:28px 12px">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:' + C.caja + ';border:1px solid ' + C.borde + ';border-radius:18px">'
  // Cabecera: Orkestador + marca
  + '<tr><td style="padding:26px 30px 0"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>'
  + '<td valign="middle" style="padding-right:14px"><img src="https://diagnostico-orkestaia.vercel.app/orkestador/orkestador-email.png" width="52" height="57" alt="" style="display:block;border:0"></td>'
  + '<td valign="middle" style="font:700 20px/1 ' + FUENTE + ';letter-spacing:1px;color:#ffffff">ORKESTA <span style="font-weight:400;font-size:14px;letter-spacing:0;color:' + C.suave + '">Automatización &amp; IA</span></td>'
  + '</tr></table></td></tr>'
  // Línea de marca cian → violeta
  + '<tr><td style="padding:22px 30px 0"><div style="height:2px;line-height:2px;font-size:0;background:' + C.cian + ';background-image:linear-gradient(90deg,' + C.cianHi + ',' + C.cian + ' 40%,#7b2cbf)">&nbsp;</div></td></tr>'
  + '<tr><td style="padding:26px 30px 30px">'
  + '<h1 style="margin:0 0 18px;font:700 24px/1.25 ' + FUENTE + ';color:#ffffff">' + esc(titulo) + '</h1>'
  + cuerpo
  + '</td></tr></table>'
  + '</td></tr></table></body></html>';
const d = $input.first().json;
return [{ json: {
  ...d,
  telegram: '✅ Visita cerrada · ' + (d.empresa || '') + '. Lista para exportar a JARVIS.\n' + ((d.urls || {}).admin || ''),
  asunto_interno: 'Visita cerrada · ' + (d.empresa || '') + ': listo para JARVIS',
  html_interno: email('Visita cerrada: ' + (d.empresa || ''), (d.empresa || '') + ': visita cerrada',
    parrafo('Lista para exportar a JARVIS.') + boton('Abrir el panel', (d.urls || {}).admin)),
  airtable: { 'Empresa': d.empresa, 'Diagnóstico ID': d.diagnostico_id, 'Estado': 'Visita cerrada', 'Actualizado': new Date().toISOString() },
} }];

// Un elemento por diagnóstico a recordar (la app ya los ha marcado como avisados).
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const C = { fondo: '#050505', caja: '#111113', borde: '#262626', texto: '#e6e6e6', suave: '#a8a8a8', cian: '#00b4d8', cianHi: '#00e5ff', violeta: '#b58cf0' };
const FUENTE = "Inter,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "'JetBrains Mono',Consolas,'Courier New',monospace";
const parrafo = t => '<p style="margin:0 0 14px;font:16px/1.6 ' + FUENTE + ';color:' + C.texto + '">' + t + '</p>';
const etiqueta = (t, color) => '<p style="margin:26px 0 10px;font:600 12px/1.2 ' + MONO + ';letter-spacing:2px;text-transform:uppercase;color:' + (color || C.cian) + '">' + esc(t) + '</p>';
const lista = (xs, color) => xs.length
  ? '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">' + xs.map(x =>
      '<tr><td width="18" valign="top" style="padding:9px 0 0"><div style="width:7px;height:7px;border-radius:7px;background:' + (color || C.cian) + '"></div></td>'
      + '<td style="padding:0 0 8px;font:15px/1.55 ' + FUENTE + ';color:' + C.texto + '">' + esc(x) + '</td></tr>').join('') + '</table>'
  : parrafo('—');
const boton = (texto, url) => '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:6px 0 4px"><tr><td style="border-radius:10px;background:' + C.cian + '">'
  + '<a href="' + esc(url) + '" style="display:inline-block;padding:12px 22px;font:600 15px ' + FUENTE + ';color:#050505;text-decoration:none;border-radius:10px">' + esc(texto) + '</a></td></tr></table>';
const email = (previa, titulo, cuerpo) => '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>' + esc(titulo) + '</title></head>'
  + '<body style="margin:0;padding:0;background:' + C.fondo + '">'
  + '<div style="display:none;max-height:0;overflow:hidden;opacity:0">' + esc(previa) + '</div>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:' + C.fondo + '"><tr><td align="center" style="padding:28px 12px">'
  + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:' + C.caja + ';border:1px solid ' + C.borde + ';border-radius:18px">'
  // Cabecera: Orkestador + marca
  + '<tr><td style="padding:26px 30px 0"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>'
  + '<td valign="middle" style="padding-right:14px"><img src="https://diagnostico-orkestaia.vercel.app/orkestador/orkestador-email.png" width="52" height="57" alt="" style="display:block;border:0"></td>'
  + '<td valign="middle" style="font:700 20px/1 ' + FUENTE + ';letter-spacing:1px;color:#ffffff">ORKESTA <span style="font-weight:400;font-size:14px;letter-spacing:0;color:' + C.suave + '">Automatización &amp; IA</span></td>'
  + '</tr></table></td></tr>'
  // Línea de marca cian → violeta
  + '<tr><td style="padding:22px 30px 0"><div style="height:2px;line-height:2px;font-size:0;background:' + C.cian + ';background-image:linear-gradient(90deg,' + C.cianHi + ',' + C.cian + ' 40%,#7b2cbf)">&nbsp;</div></td></tr>'
  + '<tr><td style="padding:26px 30px 30px">'
  + '<h1 style="margin:0 0 18px;font:700 24px/1.25 ' + FUENTE + ';color:#ffffff">' + esc(titulo) + '</h1>'
  + cuerpo
  + '</td></tr></table>'
  + '</td></tr></table></body></html>';
const r = $input.first().json;
return (r.pendientes || []).map(p => {
  const nombre = (p.contacto.nombre || '').trim();
  // El texto del recordatorio lo redacta la app (mensajeRecordatorio); aquí solo se maqueta.
  const lineas = String(p.mensaje).split('\n').filter(x => x.trim() && x.trim() !== p.enlace);
  return { json: {
    ...p,
    asunto: 'Te recuerdo las preguntas del diagnóstico, ' + nombre,
    html: email('Son 5 minutos y el enlace guarda lo que ya hayas contestado.', 'Hola, ' + nombre + '.',
      lineas.map(l => parrafo(esc(l.replace(/^Hola [^,]*, /, '')))).join('') + boton('Seguir con las preguntas', p.enlace)),
    telegram: '⏰ ' + p.empresa + ' no ha terminado el previo (' + p.respondidas + '/' + p.total + ').\n'
      + (p.contacto.email ? 'Le he enviado un recordatorio por email.\n' : 'No tiene email: mándale el recordatorio tú.\n')
      + (p.whatsapp ? 'WhatsApp con el mensaje escrito: ' + p.whatsapp : 'Sin teléfono.'),
    airtable: {
      'Empresa': p.empresa,
      'Diagnóstico ID': p.diagnostico_id,
      'Estado': 'Recordatorio enviado',
      'Contacto': nombre,
      'Email': p.contacto.email || null,
      'Teléfono': p.contacto.telefono || null,
      'Enlace del previo': p.enlace,
      'Actualizado': new Date().toISOString(),
    },
  } };
});
